input.command:
mkdir bootstrap && cd bootstrap && cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type        = string
  description = "AWS region the state bucket and its KMS key are created in."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. S3 bucket names are global, so choose one that is unique to your organization."
}

variable "noncurrent_version_retention_days" {
  type        = number
  description = "Days a superseded state version is kept before it is deleted. Older versions can be restored until then."
  default     = 90
}
EOF
cat > main.tf <<'EOF'
resource "aws_kms_key" "state" {
  description             = "Encrypts Terraform state in ${var.state_bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "state" {
  name          = "alias/${var.state_bucket_name}"
  target_key_id = aws_kms_key.state.key_id
}

resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.state.arn
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket_name" {
  description = "Name of the state bucket. Use it as the bucket value in the backend block."
  value       = aws_s3_bucket.state.id
}

output "state_kms_key_arn" {
  description = "ARN of the KMS key that encrypts state. Principals that run Terraform need kms:Decrypt, kms:GenerateDataKey and kms:DescribeKey on it."
  value       = aws_kms_key.state.arn
}
EOF
cat > terraform.tfvars.example <<'EOF'
state_bucket_name = "example-org-terraform-state"
EOF
cd .. && cat >> versions.tf <<'EOF'
EOF
python3 - <<'EOF'
p='versions.tf'
s=open(p).read()
s=s.replace('''  required_version = ">= 1.10.0"
''','''  required_version = ">= 1.10.0"

  backend "s3" {
    bucket       = "example-org-terraform-state"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }
''')
open(p,'w').write(s)
EOF
printf '*.tfstate\n*.tfstate.*\n.terraform/\n*.tfplan\n*.tfvars\n!*.tfvars.example\ncrash.log\n' > .gitignore
terraform fmt -recursive -check -diff; (cd bootstrap && terraform init -backend=false -input=false >/dev/null && terraform validate); terraform init -backend=false -input=false >/dev/null && terraform validate; git status --short

